INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 9, 'theory', 'Quiz: dictionaries');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 0, 'prices = {"apple": 50}. What will prices.get("kiwi", 0) return?', '["A KeyError", "None", "0", "50"]', 2, 'get does not fail on a missing key and returns the fallback value, here 0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 1, 'prices = {"apple": 50}. What will 50 in prices return?', '["True", "False", "An error", "50"]', 1, 'The in operator on a dictionary checks keys, and 50 is a value. For values you need 50 in prices.values().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 2, 'What happens on prices["kiwi"] = 90 if the key "kiwi" is not yet in the dictionary?', '["Python raises a key error", "A new pair appears in the dictionary", "The first pair is overwritten", "Nothing changes"]', 1, 'Assignment by key both adds a new pair and replaces the value of an existing one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 3, 'Which line correctly counts the frequencies of words w in the dictionary counts?', '["counts[w] = counts[w] + 1", "counts[w] += 1 without creating the key", "counts[w] = counts.get(w, 0) + 1", "counts.add(w)"]', 2, 'The first two fail with a key error on a new word; get with zero creates the pair on first sight.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 4, 'What cannot be used as a dictionary key?', '["A string", "A number", "A tuple", "A list"]', 3, 'A key must be immutable: a list changes in place, so Python answers with TypeError: unhashable.');
